# owner: platform
"""Contact sheet rows for substitute teachers."""

import rosterkit.errors


def _check(students):
    if not students:
        raise rosterkit.errors.ProjectError("no students given")
    for student in students:
        if not student.email:
            raise rosterkit.errors.ProjectError(
                f"no email for {student.display_name}"
            )


def _sort_key(student):
    return student.display_name.casefold()


def _widths(cells):
    widths = [0, 0]
    for name, section, _email in cells:
        widths[0] = max(widths[0], len(name))
        widths[1] = max(widths[1], len(section))
    return widths


def contact_rows(students):
    """Text rows sorted by name: name, section and email."""
    _check(students)
    cells = []
    for s in sorted(students, key=_sort_key):
        cells.append((s.display_name, s.section, s.email))
    widths = _widths(cells)
    rows = []
    for name, section, email in cells:
        rows.append(
            f"{name:<{widths[0]}}  {section:<{widths[1]}}  {email}"
        )
    return rows
EOF
cat > tests/test_contacts.py <<'EOF'
# owner: platform
import unittest

import rosterkit.models
import rosterkit.errors
import rosterkit.contacts


def _student(last, first, section="A", email="x@example.org"):
    return rosterkit.models.Student(
        "1", last, first, section, email
    )


class ContactRowsTests(unittest.TestCase):
    def test_sorted_by_name(self):
        rows = rosterkit.contacts.contact_rows(
            [_student("Zed", "Al"), _student("Abe", "Bo")]
        )
        self.assertTrue(rows[0].startswith("Abe, Bo"))
        self.assertTrue(rows[1].startswith("Zed, Al"))

    def test_columns_line_up(self):
        rows = rosterkit.contacts.contact_rows(
            [
                _student("Lee", "Al", "A", "a@x.org"),
                _student("Longname", "Bo", "B", "b@x.org"),
            ]
        )
        self.assertTrue(rows[0].index("a@x.org") == (
            rows[1].index("b@x.org")
        ))
        self.assertTrue(len(rows) == 2)

    def test_missing_email_names_student(self):
        with self.assertRaises(rosterkit.errors.ProjectError) as ctx:
            rosterkit.contacts.contact_rows(
                [_student("Lee", "Al", email=None)]
            )
        self.assertTrue("Lee, Al" in str(ctx.exception))

    def test_empty_list(self):
        with self.assertRaises(rosterkit.errors.ProjectError):
            rosterkit.contacts.contact_rows([])
